	'dashboard.onboarding_intro.eyebrow' => 'FCC guide',
	'dashboard.onboarding_intro.title' => 'Start simply and understand what you already have in one place',
	'dashboard.onboarding_intro.text' => 'FCC gives you a personal app, blog content, funnel tools, support and AI recommendations so you can create more interest toward Forever products, registrations and contacts.',
	'dashboard.onboarding_intro.item_1_title' => 'FCC apps and share links',
	'dashboard.onboarding_intro.item_1_text' => 'Edit your app and share links that lead to your recommendation.',
	'dashboard.onboarding_intro.item_2_title' => 'Clicks, registrations and contacts',
	'dashboard.onboarding_intro.item_2_text' => 'See right away what creates interest, where registrations and contacts happen, and what is worth repeating.',
	'dashboard.onboarding_intro.item_3_title' => 'AI and support',
	'dashboard.onboarding_intro.item_3_text' => 'AI helps with next actions, while support lets you ask questions and suggest webinar topics.',
	'dashboard.onboarding_intro.primary' => 'Start tutorial',
	'dashboard.onboarding_intro.secondary' => 'How FCC works',
	'dashboard.onboarding_modal.title' => 'How FCC works',
	'dashboard.onboarding_modal.subtitle' => 'In 6 short steps, see what you have, what it gives you and what to do first.',
	'dashboard.onboarding_modal.step_1_title' => '1. Dashboard as your starting point',
	'dashboard.onboarding_modal.step_1_text' => 'The dashboard is your main place for understanding the FCC system: here you see your activity signal, educational guides, next actions and the overview of what already brings results.',
	'dashboard.onboarding_modal.step_2_title' => '2. Main menus and content',
	'dashboard.onboarding_modal.step_2_text' => 'Through the main menu you open Forever Card Club content, Forever Products, the blog, contact and the dashboard. This is the path you use to learn, share content and build your Forever business.',
	'dashboard.onboarding_modal.step_3_title' => '3. FCC apps and links',
	'dashboard.onboarding_modal.step_3_text' => 'Your FCC apps act as your personal digital base from which you guide visitors toward products, registrations, contacts and other key actions.',
	'dashboard.onboarding_modal.step_4_title' => '4. Blog and recommendations',
	'dashboard.onboarding_modal.step_4_text' => 'The blog and Forever Products section are used to share educational and product content with your recommendation so interest toward products and the webshop stays connected to you.',
	'dashboard.onboarding_modal.step_5_title' => '5. Signal, AI and Your growth plan',
	'dashboard.onboarding_modal.step_5_text' => 'FCC tracks which actions truly lead toward the Forever webshop, and AI uses that signal to suggest clearer next moves and a better growth plan.',
	'dashboard.onboarding_modal.step_6_title' => '6. Support, education and webinar topics',
	'dashboard.onboarding_modal.step_6_text' => 'When you get stuck or want a new direction, support and webinar topics give you extra explanation, help and a place to suggest what matters most for your next stage of growth.',
	'dashboard.onboarding_modal.primary' => 'Start tutorial',
	'dashboard.onboarding_modal.secondary' => 'Just show me around',
	'dashboard.tutorials.eyebrow' => 'Quick guides',
	'dashboard.tutorials.title' => 'Tutorials for your first recommendations',
	'dashboard.tutorials.text' => 'Open short guides for specific actions that help you increase interest, clicks and recommendations through the FCC system.',
	'dashboard.tutorials.blog_referral.badge' => 'FCC blog + recommendation',
	'dashboard.tutorials.blog_referral.title' => 'Share an article with your own recommendation link',
	'dashboard.tutorials.blog_referral.text' => 'This guide takes you from the Forever Products section to a ready-made link that automatically connects your content, recommendation and webshop visit.',
	'dashboard.tutorials.blog_referral.button' => 'Start guide',
	'dashboard.tutorials.blog_referral.modal_title' => 'How to share an article with your own recommendation link',
	'dashboard.tutorials.blog_referral.modal_subtitle' => 'From opening the Forever Products section to copying a ready-made link that already contains your recommendation.',
	'dashboard.tutorials.blog_referral.modal_callout' => 'When you share an article this way, FCC automatically adds your recommendation to the link you send. It is the simplest way to make product content work for your signal and recommendation right away.',
	'dashboard.tutorials.blog_referral.modal_primary' => 'Start step-by-step guide',
	'dashboard.tutorials.blog_referral.next_open_article' => 'Open article',
	'dashboard.tutorials.blog_referral.step_1_title' => '1. Click Forever Products',
	'dashboard.tutorials.blog_referral.step_1_text' => 'Open the Forever Products section in the left menu. This takes you to the blog with product content that is ready for sharing.',
	'dashboard.tutorials.blog_referral.step_2_title' => '2. Choose a product or find it through search',
	'dashboard.tutorials.blog_referral.step_2_text' => 'Inside the blog, choose the product you want to recommend. If you want to reach the right article faster, use search and open the product that matches the person’s interest.',
	'dashboard.tutorials.blog_referral.step_3_title' => '3. Use the share area with recommendation',
	'dashboard.tutorials.blog_referral.step_3_text' => 'At the top of the article you will see the section Share this page with your recommendation. There you can copy the link or share it immediately with the available buttons.',
	'dashboard.tutorials.blog_referral.step_4_title' => '4. The link already includes your recommendation',
	'dashboard.tutorials.blog_referral.step_4_text' => 'The link you copy or share already contains your unique recommendation link. If a visitor opens the Forever webshop through it, that visit and recommendation are connected to your account.',
	'dashboard.tutorials.blog_referral.step_5_title' => 'Why this matters',
	'dashboard.tutorials.blog_referral.step_5_text' => 'These clicks strengthen your sales signal, help position your Forever Card app and build a clear trail of interest toward Forever Living Products.',
	'dashboard.tutorials.blog_referral.category_step_1_title' => 'You are now in Forever Products',
	'dashboard.tutorials.blog_referral.category_step_1_text' => 'This is the product blog section with content you can share using your recommendation. The guide now takes you to the right article and the shareable recommendation link.',
	'dashboard.tutorials.blog_referral.category_step_2_title' => 'Find the product you want to recommend',
	'dashboard.tutorials.blog_referral.category_step_2_text' => 'If you already know which product you want to send, type it into search. That is the fastest way to reach the article that matches the person’s interest.',
	'dashboard.tutorials.blog_referral.category_step_3_title' => 'Open the product article',
	'dashboard.tutorials.blog_referral.category_step_3_text' => 'For this guide we will open the first visible article. Inside the article, the guide will continue and show you where to copy or share your recommendation link.',
	'dashboard.tutorials.blog_referral.article_step_1_title' => 'This is where the recommendation link is generated',
	'dashboard.tutorials.blog_referral.article_step_1_text' => 'At the top of the article you can see the share row with your recommendation. When you share from this area, FCC adds your personal recommendation to the link.',
	'dashboard.tutorials.blog_referral.article_step_2_title' => 'Check how the system works',
	'dashboard.tutorials.blog_referral.article_step_2_text' => 'Clicking How this works opens a short explanation that your recommendation is added automatically and that the visit remains connected to your account.',
	'dashboard.tutorials.blog_referral.article_step_3_title' => 'Share the article using ready-made buttons',
	'dashboard.tutorials.blog_referral.article_step_3_text' => 'Here you can instantly share the article on social networks or send it in a message. All options use the same link with your recommendation.',
	'dashboard.tutorials.blog_referral.article_step_4_title' => 'Copy your finished link',
	'dashboard.tutorials.blog_referral.article_step_4_text' => 'If you want to paste the link manually into a message, story or post, copy it here. A visitor who goes to the Forever webshop through that link stays connected to your recommendation.',
	'dashboard.tour.launch' => 'Start tutorial',
	'dashboard.tour.replay' => 'Replay tutorial',
	'dashboard.tour.next' => 'Next',
	'dashboard.tour.prev' => 'Back',
	'dashboard.tour.skip' => 'Skip',
	'dashboard.tour.finish' => 'Finish',
	'dashboard.tour.step_guide_title' => 'Guide for this page',
	'dashboard.tour.step_guide_text' => 'On every important FCC page, the guide is located in the top-right corner. Click that button whenever you want short step-by-step instructions for the page you are currently viewing.',
	'dashboard.tour.step_sidebar_title' => 'FCC menu and work areas',
	'dashboard.tour.step_sidebar_text' => 'This is the main FCC menu inside your user system. From here you open the dashboard, apps, your growth plan, results, education and product content that support your day-to-day Forever business.',
	'dashboard.tour.step_menu_apps_title' => 'FCC apps',
	'dashboard.tour.step_menu_apps_text' => 'This is where you open your Forever Card apps. They are your personal digital base for guiding visitors toward products, registrations, contacts and other key actions.',
	'dashboard.tour.step_menu_ai_plan_title' => 'AI Your growth plan',
	'dashboard.tour.step_menu_ai_plan_text' => 'This is where you open and follow your growth plan. AI uses the signal from your apps, blog content and webshop clicks to suggest the next best moves for the days ahead.',
	'dashboard.tour.step_menu_results_title' => 'FCC results',
	'dashboard.tour.step_menu_results_text' => 'Here you can see whether your system is truly producing results. This area helps you track clicks, progress and the signals that show what is worth strengthening.',
	'dashboard.tour.step_menu_education_title' => 'Forever education',
	'dashboard.tour.step_menu_education_text' => 'This area contains video education and explanations that help you understand the system, follow the steps and apply what you learn in everyday work.',
	'dashboard.tour.step_menu_products_title' => 'Forever Products',
	'dashboard.tour.step_menu_products_text' => 'This opens product articles and recommendation content. It is one of the main places from which you share content with your recommendation and lead interest toward the Forever webshop.',
	'dashboard.tour.step_navbar_title' => 'Main FCC menu',
	'dashboard.tour.step_navbar_text' => 'The top menu is your main navigation through education, products, blog content, contact and the return to the dashboard. This is where understanding the whole FCC system begins.',
	'dashboard.tour.step_menu_forever_club_title' => 'Forever Card Club',
	'dashboard.tour.step_menu_forever_club_text' => 'This opens the main FCC information, system explanations and content that helps you understand how apps, recommendations and tools work together to build a Forever business.',
	'dashboard.tour.step_menu_forever_products_title' => 'Forever Products',
	'dashboard.tour.step_menu_forever_products_text' => 'This opens product content and articles you can share with your recommendation. It is an important part of creating interest and leading visitors toward the Forever webshop.',
	'dashboard.tour.step_menu_blog_title' => 'Blog',
	'dashboard.tour.step_menu_blog_text' => 'The blog gives you broader educational and business content you can use in posts, messages and trust-building through useful content, not only through direct selling.',
	'dashboard.tour.step_menu_contact_title' => 'Contact',
	'dashboard.tour.step_menu_contact_text' => 'This is where contact and support are available for additional questions. When something is unclear or you need direction, this is one of the places where you ask for help.',
	'dashboard.tour.step_menu_dashboard_title' => 'Dashboard',
	'dashboard.tour.step_menu_dashboard_text' => 'The dashboard is your command center. Here you follow your signal, learn through guides, see what works and decide what your next step should be.',
	'dashboard.tour.step_hero_title' => 'Homepage of your FCC work',
	'dashboard.tour.step_hero_text' => 'This top section sums up where you currently are, what your focus is and which are your fastest entry points toward apps, support and educational guides.',
	'dashboard.tour.step_growth_title' => 'Signal and unlocks',
	'dashboard.tour.step_growth_text' => 'Here you can see how much real activity leads toward the Forever Living webshop through your FCC app, blog and other tools. That signal shapes the pace of AI help and the next unlocks inside your growth plan.',
	'dashboard.tour.step_tutorials_title' => 'Mini tutorials and education',
	'dashboard.tour.step_tutorials_text' => 'Here you open short practical guides for specific actions. This is how FCC education works in practice: not only through theory, but through small steps you can apply immediately.',
	'dashboard.tour.step_workbench_title' => 'Workbench',
	'dashboard.tour.step_workbench_text' => 'Here you immediately see what works, where the result leaks and which parts of the system already bring interest. This helps you make decisions based on real signals, not guesswork.',
	'dashboard.tour.step_chart_title' => 'Clicks that build results',
	'dashboard.tour.step_chart_text' => 'The chart separates app → Forever, blog → Forever, registrations, and contacts from the funnel and AI chat so you can clearly see which part of the system creates the real business signal.',
	'dashboard.tour.step_next_action_title' => 'Your next move',
	'dashboard.tour.step_next_action_text' => 'This block gives you one clear recommendation for what to do now. The goal of FCC is not to overload you with data, but to help you choose the most useful next step.',
	'dashboard.tour.step_support_title' => 'Support and webinar topics',
	'dashboard.tour.step_support_text' => 'This is where you open support, read admin replies and propose webinar topics you want us to cover. It is part of FCC education that helps when you get stuck or want deeper understanding.',
