	'qr_codes.header' => 'QR codes',
	'qr_codes.subheader' => 'Easily create customizable QR codes & remember them for later use.',
	'qr_codes.page_intro' => 'Create standalone QR codes for print, offline sharing, events, products, WiFi, contact handoff, and many other scenarios. Each Forever Card App can also create its own direct QR, while this section gives you a separate QR workspace for building and editing them in one place.',
	'qr_codes.guide_title' => 'A separate QR workspace for print, offline sharing, and controlled use cases',
	'qr_codes.guide_text' => 'This QR section is for standalone QR assets you want to manage outside a specific app screen. Use it when you need printable QR codes, reusable campaign codes, event or product access points, or a QR that deserves its own styling and export workflow.',
	'qr_codes.guide_card_1_title' => 'Separate from the app QR',
	'qr_codes.guide_card_1_text' => 'Every Forever Card App can generate its own direct QR, but here you can create fully separate QR codes for other landing pages, links, materials, and campaigns.',
	'qr_codes.guide_card_2_title' => 'Built for print and offline use',
	'qr_codes.guide_card_2_text' => 'These QR codes are ideal for flyers, business cards, posters, product sheets, event tables, packaging, and in-person sharing where people scan instead of typing.',
	'qr_codes.guide_card_3_title' => 'Customize and export properly',
	'qr_codes.guide_card_3_text' => 'Control the QR type, style, colors, frames, logo, branding, and file output so the final code fits the context where it will be used.',
	'qr_codes.guide_card_4_title' => 'Edit and reuse later',
	'qr_codes.guide_card_4_text' => 'Once created, each QR stays available for download, print, duplication, and later refinement without rebuilding it from scratch.',
	'qr_codes.empty_title' => 'Create your first QR code',
	'qr_codes.empty_text' => 'Start with a standalone QR for a link, app, contact, event, or print material. After creation, you can return to edit the style, frame, branding, and export format.',
	'qr_codes.tour.create_title' => 'Create a standalone QR code',
	'qr_codes.tour.create_text' => 'Use this button when you want a QR that lives outside a single Forever Card App page. It is ideal for campaigns, print materials, events, and reusable offline sharing.',
	'qr_codes.tour.guide_title' => 'Understand when this section is the right place',
	'qr_codes.tour.guide_text' => 'This guide explains the difference between app-specific QR codes and standalone QR assets. The goal is to help users choose the right flow before creating or editing.',
	'qr_codes.tour.list_title' => 'Your QR library stays organized here',
	'qr_codes.tour.list_text' => 'This list becomes the control center for every standalone QR code: preview, name, type, project relation, export actions, and edit access all stay together.',
	'qr_codes.tour.row_title' => 'Each row is a reusable QR asset',
	'qr_codes.tour.row_text' => 'A QR code here can represent a URL, app link, event, WiFi handoff, vCard, payment request, or many other scan experiences. You can keep refining the same asset over time.',
