	'qr_codes.editor.hero_title' => 'Turn a simple QR into a reusable offline-to-digital access point',
	'qr_codes.editor.hero_text' => 'This editor is where a QR code becomes practical, branded, and ready for real use. Every Forever Card App can generate its own QR, but here you can separately create and refine QR codes for print, campaigns, events, product journeys, contact sharing, and many other scan scenarios.',
	'qr_codes.editor.hero_card_1_title' => 'Choose the scan outcome',
	'qr_codes.editor.hero_card_1_text' => 'Decide whether the QR should open a URL, contact card, payment flow, WiFi connection, message draft, event, location, or another supported action.',
	'qr_codes.editor.hero_card_2_title' => 'Design it for the context',
	'qr_codes.editor.hero_card_2_text' => 'Adjust style, colors, frame, branding, and optional logo so the QR fits a flyer, business card, product sheet, presentation, or event material.',
	'qr_codes.editor.hero_card_3_title' => 'Preview before printing',
	'qr_codes.editor.hero_card_3_text' => 'Use the live preview, readability check, and download options to test before the QR is printed or distributed publicly.',
	'qr_codes.editor.hero_card_4_title' => 'Reuse instead of rebuilding',
	'qr_codes.editor.hero_card_4_text' => 'Once a QR works well, keep editing, duplicating, or exporting it for new campaigns instead of starting over every time.',
	'qr_codes.editor.tour.intro_title' => 'QR editor overview',
	'qr_codes.editor.tour.intro_text' => 'This page helps you build or refine a standalone QR code that can be printed, shared, exported, and reused across many contexts.',
	'qr_codes.editor.tour.type_title' => 'Choose what the scan should do',
	'qr_codes.editor.tour.type_text' => 'The QR type defines the actual outcome for the scanner: open a link, save contact info, launch a message, connect to WiFi, show a payment request, and more.',
	'qr_codes.editor.tour.basics_title' => 'Start with name and main data',
	'qr_codes.editor.tour.basics_text' => 'Give the QR a clear internal name and fill the essential content fields. This is the core payload that will be embedded in the code.',
	'qr_codes.editor.tour.style_title' => 'Shape the QR pattern itself',
	'qr_codes.editor.tour.style_text' => 'Style controls the geometry of the QR modules and eyes. This is useful when the QR should visually match a brand, campaign, or printed piece.',
	'qr_codes.editor.tour.colors_title' => 'Control contrast and scan clarity',
	'qr_codes.editor.tour.colors_text' => 'Colors are not only aesthetic. Good contrast is critical for scanning reliability, especially when the QR will be printed or viewed under imperfect lighting.',
	'qr_codes.editor.tour.frame_title' => 'Add context around the QR',
	'qr_codes.editor.tour.frame_text' => 'Frames help a QR look more intentional and can add a call to action or label so people immediately understand why they should scan it.',
	'qr_codes.editor.tour.branding_title' => 'Add logo and branded layers carefully',
	'qr_codes.editor.tour.branding_text' => 'Branding options let you place logos and images into the QR composition, but they should be tested carefully so readability stays strong.',
	'qr_codes.editor.tour.options_title' => 'Finish technical settings',
	'qr_codes.editor.tour.options_text' => 'Size, margin, encoding, error correction, and project organization help the QR behave correctly in export and production use.',
	'qr_codes.editor.tour.preview_title' => 'Watch the final QR live',
	'qr_codes.editor.tour.preview_text' => 'The preview is where you confirm the QR still looks clean and scannable before downloading, printing, or sharing it.',
	'qr_codes.editor.tour.download_title' => 'Prepare output for print or delivery',
	'qr_codes.editor.tour.download_text' => 'Export SVG, PNG, JPG, or WEBP depending on whether you need print quality, transparency, presentation use, or quick distribution.',
	'qr_codes.editor.tour.save_title' => 'Save, test, then deploy',
	'qr_codes.editor.tour.save_text' => 'After saving, scan the QR on at least one phone before using it publicly. This is especially important when frames, gradients, logos, or printed materials are involved.',
