	'link.short_editor.hero_title' => 'Turn a simple short URL into a controlled redirect flow',
	'link.short_editor.hero_text' => 'This editor is where a short link becomes strategic. Beyond the alias and destination, you can add scheduling, UTM tracking, password protection, app linking, cloaking, device or location targeting, HTTP behavior, and other advanced controls.',
	'link.short_editor.hero_card_1_title' => 'Start with the basics',
	'link.short_editor.hero_card_1_text' => 'Define the destination URL, choose the short alias, and decide which domain the short link should use.',
	'link.short_editor.hero_card_2_title' => 'Decide how it behaves',
	'link.short_editor.hero_card_2_text' => 'Control when the link works, where it redirects, what happens after expiration, and whether it should pass query parameters forward.',
	'link.short_editor.hero_card_3_title' => 'Track and personalize',
	'link.short_editor.hero_card_3_text' => 'Add UTM tags, pixels, cloaking metadata, and app linking so every click carries the context you need.',
	'link.short_editor.hero_card_4_title' => 'Protect and optimize',
	'link.short_editor.hero_card_4_text' => 'Use passwords, sensitive-content warnings, audience targeting, and redirect codes to match each campaign and audience.',
	'link.short_editor.form_title' => 'What you can configure on a short link',
	'link.short_editor.form_text' => 'Open only the sections you need, or follow the tutorial step by step. Each group below controls one layer of the short-link experience, from simple redirects to advanced campaign logic.',
	'link.short_editor.card_1_title' => 'For clean launches',
	'link.short_editor.card_1_text' => 'Set the destination, alias, domain, and redirect code so the link works exactly as intended from the first share.',
	'link.short_editor.card_2_title' => 'For campaigns and reporting',
	'link.short_editor.card_2_text' => 'Add UTM values, pixels, reports, and projects so traffic can be measured and grouped correctly.',
	'link.short_editor.card_3_title' => 'For advanced behavior',
	'link.short_editor.card_3_text' => 'Schedule availability, set expiration rules, protect access, target audiences, or cloak the destination page when needed.',
	'link.short_editor.tour.intro_title' => 'Short-link editor overview',
	'link.short_editor.tour.intro_text' => 'This page gathers all advanced options for one short link. The goal is simple: help people understand what each setting changes before they save.',
	'link.short_editor.tour.basics_title' => 'Basics come first',
	'link.short_editor.tour.basics_text' => 'Here you define where the short link points, what alias it uses, and which domain it should live on. These are the core redirect settings.',
	'link.short_editor.tour.app_linking_title' => 'Open mobile apps directly',
	'link.short_editor.tour.app_linking_text' => 'App linking helps supported mobile destinations open inside the native app instead of only in the browser, which can improve user experience on phones.',
	'link.short_editor.tour.temporary_title' => 'Set timing and expiry rules',
