	'fcc.page.semantics_heading' => 'What Is Forever Card Club (FCC)?',
	'fcc.page.semantics_summary' => 'Forever Card Club (FCC) is an all-in-one digital business system for Forever Living Products partners. FCC combines a personal app, smart referral links, AI product assistants, lead funnel logic, education, analytics, and a physical NFC card into one business workflow.',
	'fcc.page.semantics_fact_1' => 'Forever Card Club is not an official Forever Living Products website or store, but an independent system for partners.',
	'fcc.page.semantics_fact_2' => 'The Forever Card App is the personal app each member receives, while FCC refers to the wider system.',
	'fcc.page.semantics_fact_3' => 'Product purchases are completed through the official Forever web shop in the customer\'s country.',
	'fcc.page.semantics_fact_4' => 'The system is designed for online sharing, referral routing, lead capture, AI guidance, and Forever business growth.',
	'fcc.page.semantics_solves_heading' => 'What does FCC solve?',
	'fcc.page.semantics_solve_1' => 'One central place for the partner app, content, products, and contact actions.',
