	'fcc.page.semantics_solve_3' => 'Lead capture and faster follow-up after interest or recommendation.',
	'fcc.page.semantics_solve_4' => 'AI-guided product discovery and next-step guidance inside the system.',
	'fcc.page.semantics_solve_5' => 'A clear bridge from offline contact through NFC/QR into the online workflow.',
	'fcc.page.term_description' => 'Forever Card Club (FCC) is an all-in-one digital business system for Forever Living Products partners that includes a personal app, smart referral links, AI product assistants, lead funnel logic, education, analytics, and a physical NFC card connected to the partner\'s content and recommendations.',
	'fcc.page.workflow_heading' => 'How does FCC work in practice?',
	'fcc.page.workflow_intro' => 'From first attention to contact or purchase, FCC connects the key steps into one business flow.',
	'fcc.page.workflow_step_1_title' => 'Entry',
	'fcc.page.workflow_step_1_text' => 'A post, message, QR code, or NFC card brings the visitor into the system.',
	'fcc.page.workflow_step_2_title' => 'App',
	'fcc.page.workflow_step_2_text' => 'The Forever Card App opens content, products, contact actions, and recommendations.',
	'fcc.page.workflow_step_3_title' => 'Guidance',
	'fcc.page.workflow_step_3_text' => 'AI, links, and blocks route the visitor toward the right next step.',
	'fcc.page.workflow_step_4_title' => 'Action',
	'fcc.page.workflow_step_4_text' => 'The visitor leaves a lead or moves toward the official Forever shop.',
	'fcc.page.workflow_step_5_title' => 'Follow-up',
	'fcc.page.workflow_step_5_text' => 'The partner tracks interest and continues the conversation more easily.',
	'fcc.page.use_cases_heading' => 'What does FCC solve?',
	'fcc.page.use_cases_intro' => 'The same system supports several different ways of building a Forever business.',
	'fcc.page.use_case_1_title' => 'New partner',
	'fcc.page.use_case_1_text' => 'Gets a clearer digital start and a more professional first impression.',
