	'fcc_ai.platform.note_admin' => 'Technical details remain available below in expandable sections while the main screen stays clean.',
	'fcc_ai.platform.note_user' => 'See in one place how AI is enabled on the app, how Coach works, and where conversations and leads are tracked.',
	'fcc_ai.platform.list.app_blocks_title' => 'AI blocks on the app',
	'fcc_ai.platform.list.app_blocks_text' => 'Public AI is enabled by adding an AI block in FCC App settings. Once added, the AI appears on that app.',
	'fcc_ai.platform.list.coach_title' => 'FCC Coach',
	'fcc_ai.platform.list.coach_text' => 'Coach is always available inside FCC, connected to the growth plan, and built to support the platform, social media, communication, and business development.',
	'fcc_ai.platform.list.single_ai_title' => 'One AI per app',
	'fcc_ai.platform.list.single_ai_text' => 'Only one AI advisor can be active on a single FCC App. If one AI block is already added, adding another will show a warning.',
	'fcc_ai.platform.list.leads_title' => 'AI leads',
	'fcc_ai.platform.list.leads_text' => 'AI leads are saved into the existing /data inbox and linked to the related conversation.',
	'fcc_ai.guide.title' => 'How to use FCC AI',
	'fcc_ai.guide.subtitle' => 'These short guides explain what each AI can do and how to get the most value from it in everyday work.',
	'fcc_ai.guide.coach.title' => 'AI Coach',
	'fcc_ai.guide.coach.summary' => 'Support for FCC work, your growth plan, and the next practical steps.',
	'fcc_ai.guide.coach.intro' => 'FCC Coach is your personal assistant inside the platform. It is connected to your growth plan and helps you stay clear on the most useful next step.',
	'fcc_ai.guide.coach.point_1' => 'It can help with planning, priorities, focus, and the next move when you feel stuck or unsure what to do next.',
	'fcc_ai.guide.coach.point_2' => 'It gives ideas for content, communication, social media, and daily actions that support business growth.',
	'fcc_ai.guide.coach.point_3' => 'It guides you through Your Growth Plan and gives advice connected to what you need right now.',
	'fcc_ai.guide.coach.tip' => 'You get the most value when you write clearly where you are, what you want to achieve, and what kind of help you need now.',
	'fcc_ai.guide.sales.title' => 'AI for sales, recommendations, and business collaboration',
	'fcc_ai.guide.sales.summary' => 'Public AI that recommends products, uses the blog, and recognizes collaboration interest.',
	'fcc_ai.guide.sales.intro' => 'This AI talks to visitors on your FCC app, helps with products for people or pets, and guides them toward the next step, purchase, or business collaboration.',
	'fcc_ai.guide.sales.point_1' => 'It answers questions, recommends products, and can send the visitor to the right FCC blog article for deeper explanation.',
	'fcc_ai.guide.sales.point_2' => 'It follows the visitor through the full flow, from the first question to continued conversation on the blog or toward contact.',
	'fcc_ai.guide.sales.point_3' => 'It can collect data from interested visitors and save a lead so the partner can follow up.',
	'fcc_ai.guide.sales.point_4' => 'It can recognize business interest and support sponsoring by guiding the visitor toward the next meaningful step.',
	'fcc_ai.guide.sales.tip' => 'It works best when the tone is clear, the rules are strong, and the recommendation logic is explained well.',
	'fcc_ai.guide.settings.title' => 'Advisor settings',
	'fcc_ai.guide.settings.summary' => 'Where you shape how the public AI sounds, replies, and what it emphasizes.',
	'fcc_ai.guide.settings.intro' => 'In the public AI advisor settings you can adjust communication so it matches your style, audience, and the goal of the app.',
	'fcc_ai.guide.settings.point_1' => 'Assistant name and language define how the AI presents itself and what language it naturally uses.',
	'fcc_ai.guide.settings.point_2' => 'Tone helps the AI sound consultative, supportive, friendly, or more direct, depending on what you want.',
	'fcc_ai.guide.settings.point_3' => 'In persona instructions, describe the style you want: warmer approach, shorter replies, more questions, stronger product focus, or more business focus.',
	'fcc_ai.guide.settings.point_4' => 'In rules and guardrails, define what the AI should always mention, what it should avoid, and how recommendations should be phrased.',
	'fcc_ai.guide.settings.tip' => 'Short and concrete instructions usually work best. Write them like you are explaining how a strong advisor should talk to a visitor.',
	'fcc_ai.guide.inbox.title' => 'AI inbox for the last 30 days',
	'fcc_ai.guide.inbox.summary' => 'The place to track conversations, leads, and refine AI chat communication.',
	'fcc_ai.guide.inbox.intro' => 'The AI inbox shows how the assistant actually talked to real users. It is the best place to monitor quality and keep improving the assistant.',
	'fcc_ai.guide.inbox.point_1' => 'Open conversations and review where the AI replied well and where the reply could be clearer or more useful.',
	'fcc_ai.guide.inbox.point_2' => 'Watch which questions repeat often so you can improve tone, persona instructions, and rules.',
	'fcc_ai.guide.inbox.point_3' => 'If users keep asking for more explanation, shorten replies, add clearer steps, or direct them better toward the blog or contact.',
	'fcc_ai.guide.inbox.point_4' => 'Track the leads AI brings in and use that to understand where the chat helps most with sales and sponsoring.',
	'fcc_ai.guide.inbox.tip' => 'If you notice the same problem more than once, adjust the advisor settings right away. Small changes in tone and rules often create a big improvement.',
